-- Schema only. Performance indexes and partitions intentionally live in database-labs.
CREATE TABLE media_asset (id BIGSERIAL PRIMARY KEY, product_id BIGINT NOT NULL, seller_id BIGINT NOT NULL, original_object_key VARCHAR(512) NOT NULL UNIQUE, media_type VARCHAR(32) NOT NULL, status VARCHAR(32) NOT NULL, content_type VARCHAR(128) NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE media_variant (id BIGSERIAL PRIMARY KEY, asset_id BIGINT NOT NULL REFERENCES media_asset(id), placement VARCHAR(64) NOT NULL, width_px INT NOT NULL, height_px INT NOT NULL, format VARCHAR(16) NOT NULL, object_key VARCHAR(512) NOT NULL UNIQUE, byte_size BIGINT NULL, created_at TIMESTAMP NOT NULL, UNIQUE(asset_id, placement, width_px, format));
CREATE TABLE outbox_event (id BIGSERIAL PRIMARY KEY, event_id VARCHAR(36) NOT NULL UNIQUE, aggregate_id VARCHAR(128) NOT NULL, event_type VARCHAR(128) NOT NULL, payload_json JSONB NOT NULL, status VARCHAR(32) NOT NULL, created_at TIMESTAMP NOT NULL, processed_at TIMESTAMP NULL);
